// Generated by scripts/generate.mjs. Nine and twelve placements use the same pattern.
import { Block } from "foldkit";
import { Schema, Tuple } from "effect";
import * as Update from "foldkit/update";
import { defineMessageUnion } from "foldkit/message";

const Model = Schema.Struct({ count: Schema.Number });
const Message = defineMessageUnion({ Request: {}, Inform: {} });
const OutMessage = defineMessageUnion({ Notify: {} });
const Definition = Block.makeDefinition("Child", { Model, Message, OutMessage });
const ChildComposition = Definition.makeComposition();
const prepare = () =>
  ChildComposition.prepareBlock({
    init: ChildComposition.makeInit(() => ({ model: { count: 0 } })),
    update: ChildComposition.makeUpdate((model, message) =>
      message._tag === "Request"
        ? { model, outMessage: OutMessage.Notify() }
        : { model: { count: model.count + 1 } },
    ),
    operations: {
      request: () => Tuple.make(Message.Request()),
      inform: () => Tuple.make(Message.Inform()),
    },
  });
const Child: Block.FromAssemblyWithOutMessage<typeof Model, typeof prepare> =
  Block.assemble(prepare);

const Parent = Block.makeDefinition("Parent", {
  Model: Schema.Struct({
    b0: Child.Model,
    b1: Child.Model,
    b2: Child.Model,
    b3: Child.Model,
    b4: Child.Model,
    b5: Child.Model,
    b6: Child.Model,
    b7: Child.Model,
    b8: Child.Model,
    b9: Child.Model,
    b10: Child.Model,
    b11: Child.Model,
  }),
  Message: defineMessageUnion({ Start: {} }),
});

// Define the original bindings first, then select and register their policies.

const b0 = Parent.makeBinding(Child, {
  field: "b0",
  init: { contextToArgs: () => Tuple.make() },
});

const b1 = Parent.makeBinding(Child, {
  field: "b1",
  init: { contextToArgs: () => Tuple.make() },
});

const b2 = Parent.makeBinding(Child, {
  field: "b2",
  init: { contextToArgs: () => Tuple.make() },
});

const b3 = Parent.makeBinding(Child, {
  field: "b3",
  init: { contextToArgs: () => Tuple.make() },
});

const b4 = Parent.makeBinding(Child, {
  field: "b4",
  init: { contextToArgs: () => Tuple.make() },
});

const b5 = Parent.makeBinding(Child, {
  field: "b5",
  init: { contextToArgs: () => Tuple.make() },
});

const b6 = Parent.makeBinding(Child, {
  field: "b6",
  init: { contextToArgs: () => Tuple.make() },
});

const b7 = Parent.makeBinding(Child, {
  field: "b7",
  init: { contextToArgs: () => Tuple.make() },
});

const b8 = Parent.makeBinding(Child, {
  field: "b8",
  init: { contextToArgs: () => Tuple.make() },
});

const b9 = Parent.makeBinding(Child, {
  field: "b9",
  init: { contextToArgs: () => Tuple.make() },
});

const b10 = Parent.makeBinding(Child, {
  field: "b10",
  init: { contextToArgs: () => Tuple.make() },
});

const b11 = Parent.makeBinding(Child, {
  field: "b11",
  init: { contextToArgs: () => Tuple.make() },
});

const p0 = b0.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b1.inform(), b2.inform(), b3.inform()]),
  }),
});

const p1 = b1.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b2.inform(), b3.inform(), b4.inform()]),
  }),
});

const p2 = b2.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b3.inform(), b4.inform(), b5.inform()]),
  }),
});

const p3 = b3.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b4.inform(), b5.inform(), b6.inform()]),
  }),
});

const p4 = b4.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b5.inform(), b6.inform(), b7.inform()]),
  }),
});

const p5 = b5.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b6.inform(), b7.inform(), b8.inform()]),
  }),
});

const p6 = b6.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b7.inform(), b8.inform(), b9.inform()]),
  }),
});

const p7 = b7.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b8.inform(), b9.inform(), b10.inform()]),
  }),
});

const p8 = b8.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b9.inform(), b10.inform(), b11.inform()]),
  }),
});

const p9 = b9.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b10.inform(), b11.inform(), b0.inform()]),
  }),
});

const p10 = b10.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b11.inform(), b0.inform(), b1.inform()]),
  }),
});

const p11 = b11.withOutMessagePolicy({
  fold: Parent.makeOutMessageFold(Child, {
    Notify: () => Update.combineSteps([b0.inform(), b1.inform(), b2.inform()]),
  }),
});
const Composition = Parent.makeComposition({
  bindings: [p0, p1, p2, p3, p4, p5, p6, p7, p8, p9, p10, p11],
});

// Native TypeScript reports TS2589/TS5114/TS5115 here for twelve placements.
const update = Composition.makeUpdate((model) => b0.request()(model));
const init = Composition.makeInit(() => ({ model: {} }));

// Request emits Notify once. Inform increments a counter without emitting Notify.
// The static graph is reciprocal, but this actual synchronous dispatch terminates.
const result = update(init().model, Composition.Message.Start());
const counts = Object.values(result.model).map((child) => child.count);
const expected = Array.from({ length: 12 }, (_, i) => (i >= 1 && i <= 3 ? 1 : 0));
if (JSON.stringify(counts) !== JSON.stringify(expected)) {
  throw new Error("Unexpected child transitions: " + JSON.stringify(counts));
}
if ((result.commands?.length ?? 0) !== 0) throw new Error("Unexpected commands");
console.log(JSON.stringify({ placements: 12, counts, commands: 0 }));

